NEW_FILES = ["INSTALL-LEGAL-UPDATE.txt", "tools/legal-update-files/src_data_returns.js.staged", "tools/legal-update-files/test_legal-update.test.js.staged"]

root = pathlib.Path('.')
if not (root / 'src').exists() or not (root / 'package.json').exists():
    print('NOT FOUND  src or package.json (run this from the project folder)')
